shortcuts.codeOnPrepare:
/*{sanitise_input}*/

// 1. Grab text from the Share Sheet variable
const link = getVariable("sanitise_input");

// 2. Strip everything from '?' onward (removes tracking parameters)
const linkSani = link.split('?')[0].trim();


// Quick visual confirmation that the script fired
//showToast('Cleaned: ' + linkSani);

// 3. Output directly via Android's native Share Sheet
shareText(linkSani);
